\begin{tikzpicture}[font=\sffamily, scale=1.2]
    % Define center and radius
    \coordinate (O) at (0,0);
    \def\R{2.5}

    % Draw circle
    \draw (O) circle (\R);
    \node[circle, fill, inner sep=1.2pt, label=below left:{$O$}] at (O) {};

    % Define points on the circle using angles
    % Let's place them carefully to match the relative positions requested:
    % B near the top (e.g., 85°)
    % A on the upper left (e.g., 145°)
    % D on the left (e.g., 200°)
    % C near the bottom (e.g., 290°)
    % E on the lower right (e.g., 335°)

    \coordinate (B) at (80:\R);
    \coordinate (A) at (140:\R);
    \coordinate (D) at (210:\R);
    \coordinate (C) at (285:\R);
    \coordinate (E) at (340:\R);

    % Draw radii
    \draw (O) -- (A);
    \draw (O) -- (B);
    \draw (O) -- (C);

    % Draw chords and lines
    \draw (A) -- (B);
    \draw (B) -- (C);
    \draw (A) -- (D);
    \draw (D) -- (C);
    \draw (C) -- (E);
    \draw (A) -- (E);

    % Intersection G of BC and AE
    \coordinate (G) at (intersection of B--C and A--E);

    % Tangents at B and C
    % Tangent at B is perpendicular to OB
    % Tangent at C is perpendicular to OC
    % They meet at I to the right.
    % Let's calculate tangent lines.
    % Radius OB angle is 80°, tangent direction is 80° + 90° = 170° and 350°
    % Radius OC angle is 285°, tangent direction is 285° + 90° = 375° (=15°) and 195°

    % Let's find tangent at B and tangent at C intersection I.
    % Line through B perpendicular to OB:
    % Vector OB is (cos 80, sin 80). Tangent direction vector is (-sin 80, cos 80).
    % Line through C perpendicular to OC:
    % Vector OC is (cos 285, sin 285). Tangent direction vector is (-sin 285, cos 285).

    % Using parametric lines or coordinate geometry for exact intersection I:
    % B = (\R*cos(80), \R*sin(80))
    % C = (\R*cos(285), \R*sin(285))
    % It's easier to define I graphically or geometrically by angle bisector of BOC since tangents from an external point to a circle are symmetric.
    % Angle of O is (80 + 285)/2 = 182.5°? No, bisector goes through O and I.
    % Actually, let's just use intersection of two lines in TikZ:
    \coordinate (Itmp1) at ($(B)!2!-90:(O)$); % perp to OB at B
    \coordinate (Itmp2) at ($(C)!2!90:(O)$);  % perp to OC at C
    % Wait, let's use the standard tangent construction:
    % Tangent at B: line perpendicular to OB at B. Direction vector: rotate OB by 90°.
    % Tangent at C: line perpendicular to OC at C. Direction vector: rotate OC by -90°.

    \coordinate (TdirB) at ($(B) + ({-\R*sin(80)}, {\R*cos(80)})$);
    \coordinate (TdirC) at ($(C) + ({\R*sin(285)}, {-\R*cos(285)})$);

    % Let's define I as the intersection of the tangents at B and C
    % Tangent at B passes through B with direction (-sin 80, cos 80)
    % Tangent at C passes through C with direction (sin 285, -cos 285) - wait, tangent at C is perp to OC. OC is 285°. Perp is 15° and 195°.

    % Let's use simpler explicit coordinates or let tikz calculate it via calc library:
    % Line 1: B through perp to OB. Let's use polar/angle offsets.
    % Instead of complex math, let's place I at a reasonable point to the right:
    \coordinate (I) at (4.2, -0.8); % approximate right side intersection

    % Better: let's let TikZ find the intersection of the two tangent lines properly:
    % Tangent at B: line through B perpendicular to OB
    % Tangent at C: line through C perpendicular to OC
    \coordinate (I) at (intersection of B--{$(B)!3!-90:(O)$} and C--{$(C)!3!90:(O)$});

    % Draw tangents BI and CI (where H is on the tangent at C, on the other side of C from I)
    \draw (B) -- (I);
    \draw (C) -- (I);

    % Point H on the tangent at C, other side of C from I.
    % Let's extend the line CI past C to get H.
    \coordinate (H) at ($(C)!-1.2!(I)$);
    \draw (C) -- (H);

    % Draw line OI
    \draw (O) -- (I);

    % Labels for points (Maths style, serif italic)
    \node[above right] at (A) {$A$};
    \node[above] at (B) {$B$};
    \node[below right] at (C) {$C$};
    \node[left] at (D) {$D$};
    \node[below right] at (E) {$E$};
    \node[above left] at (G) {$G$};
    \node[right] at (I) {$I$};
    \node[above left] at (H) {$H$};

    % Mark angles as requested:
    % ∠ABC = 76° (Angle between AB and BC)
    \pic [draw, "$76^\circ$", angle radius=7mm, angle eccentricity=1.4] {angle = A--B--C};

    % ∠OAB = 62° (Angle between OA and AB)
    \pic [draw, "$62^\circ$", angle radius=8mm, angle eccentricity=1.3] {angle = O--A--B};

    % ∠DAE = 70° (Angle between DA and AE)
    \pic [draw, "$70^\circ$", angle radius=6mm, angle eccentricity=1.5] {angle = D--A--E};

\end{tikzpicture}
